import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;

  // Create group for this card label
  const group = new THREE.Group();
  group.position.set(3.2, 1, 0.06);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  // Cleanup tracking
  const timelines = [];
  const resources = [];

  // Create the plane geometry (512x320 texture from atlas)
  // Scale to match aspect ratio and reasonable size in scene
  const width = 0.85;
  const height = (320 / 512) * width;
  const geometry = new THREE.PlaneGeometry(width, height);
  resources.push(geometry);

  // Load the texture asynchronously
  ctx.textureLoader.loadTexture(config.imageUrl).then((texture) => {
    texture.colorSpace = THREE.SRGBColorSpace;
    texture.magFilter = THREE.LinearFilter;
    texture.minFilter = THREE.LinearMipmapLinearFilter;

    // Create material with the loaded texture
    const material = new MeshBasicNodeMaterial();
    material.colorNode = uv();
    material.map = texture;
    material.needsUpdate = true;

    // Create mesh
    const mesh = new THREE.Mesh(geometry, material);
    group.add(mesh);
    resources.push(material);
    resources.push(texture);
  });

  // Render text content from config.textContent
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  for (const item of items) {
    const textObj = ctx.fontAtlas.createText(String(item.text), {
      fontSize: item.typography?.fontSize ?? 39,
      color: item.typography?.color ?? '#16161d',
      align: 'center'
    });
    textObj.position.y = -(height / 2 + 0.2);
    group.add(textObj);
  }

  // Idle breathing animation on the card (subtle vertical translate)
  const breatheTimeline = gsap.timeline({ repeat: -1, yoyo: true });
  breatheTimeline.to(group.position, {
    y: 1.05,
    duration: 2.5,
    ease: 'sine.inOut'
  }, 0);
  timelines.push(breatheTimeline);

  // Store handlers and cleanup
  group.userData.handlers = {};

  group.userData.cleanup = () => {
    timelines.forEach((tl) => tl.kill());
    resources.forEach((res) => {
      if (res.dispose) res.dispose();
    });
  };

  return group;
}
